# Sourced by the Mac build and test scripts: sets MAC_SIGNING, the xcodebuild signing arguments.
#
# Unset MESHLIVE_SIGN_IDENTITY (the default): ad-hoc signing, as generated by Scripts/project.py. No account is
# needed, but macOS ties privacy permissions (Bluetooth, camera, microphone) and Keychain access to the code hash,
# so every rebuild asks again.
# MESHLIVE_SIGN_IDENTITY=<SHA-1 or name>: sign with your own code-signing identity from your keychain
# (`security find-identity -v -p codesigning`, for example your "Apple Development" certificate). The app then keeps
# a stable code identity and its permissions survive rebuilds.
# MESHLIVE_TEAM=<team ID>: optional, only when Xcode asks for a development team.
# Nothing here is written to the project; keep your identity and team in your shell environment.
MAC_SIGNING=()
if [[ -n "${MESHLIVE_SIGN_IDENTITY:-}" ]]; then
    if ! security find-identity -v -p codesigning | grep -qF -- "$MESHLIVE_SIGN_IDENTITY"; then
        echo "MESHLIVE_SIGN_IDENTITY matches no valid code-signing identity (security find-identity -v -p codesigning)" >&2
        return 1 2>/dev/null || exit 1
    fi
    MAC_SIGNING=(CODE_SIGN_STYLE=Manual "CODE_SIGN_IDENTITY=$MESHLIVE_SIGN_IDENTITY" PROVISIONING_PROFILE_SPECIFIER=)
    if [[ -n "${MESHLIVE_TEAM:-}" ]]; then MAC_SIGNING+=("DEVELOPMENT_TEAM=$MESHLIVE_TEAM"); fi
    echo "Mac signing: your identity from MESHLIVE_SIGN_IDENTITY" >&2
else
    echo "Mac signing: ad-hoc (set MESHLIVE_SIGN_IDENTITY to keep permissions across rebuilds)" >&2
fi
